const express = require('express');
const app = express();

// URL: /api/products?category=shoes&sort=price_desc
app.get('/api/products', (req, res) => {
  const { category, sort } = req.query;

  res.json({
    action: 'Filtering products',
    filters: {
      category: category || 'all',
      sortBy: sort || 'newest'
    }
  });
});
